using System;
using System.Collections.Generic;
using System.IO;
namespace Downfield {
public static class LeagueDevelopmentTests {
 static int checks,failures;static void Check(bool ok,string message){checks++;if(!ok){failures++;Console.WriteLine("FAIL League: "+message);}}
 static Franchise New(){return Franchise.Create(new Profile(),new Roster());}
 static void FinishSeason(Franchise f){int guard=0;while(!f.Complete&&guard++<15){if(f.UserGame==null)f.Advance();else f.FinishGame(f.UserGame.Id,28,14);}Check(f.Complete,"season finishes with AI roster decisions");}
 public static int Run(){checks=failures=0;string old=Profile.StorageOverride,folder=Path.Combine(Path.GetTempPath(),"Downfield-league-"+Guid.NewGuid().ToString("N"));Profile.StorageOverride=Path.Combine(folder,"club.txt");try{
  Franchise f=New();Check(Franchise.Cap==190&&Franchise.ContractSalary(99)>=20&&Franchise.ContractSalary(80)<8,"cap and elite salary prevent an all-star roster");
  Dictionary<int,int> original=new Dictionary<int,int>();HashSet<int> free=new HashSet<int>();foreach(ClubPlayer p in f.Players){original[p.Id]=p.OVR;if(p.Team==-1)free.Add(p.Id);}FinishSeason(f);int improved=0,signed=0;HashSet<int> growing=new HashSet<int>();foreach(ClubPlayer p in f.Players)if(p.Team>=0&&p.Team!=f.UserTeam){if(original.ContainsKey(p.Id)&&p.OVR>original[p.Id]){improved++;growing.Add(p.Team);}if(free.Contains(p.Id))signed++;}Console.WriteLine("CPU league: "+improved+" players improved across "+growing.Count+" clubs; "+signed+" original free agents signed.");Check(improved>100&&growing.Count==11,"all eleven CPU clubs develop their players");Check(signed>=10,"CPU clubs compete for the shared free-agent market");
  List<Standing> table=f.Table();int worst=table[11].Team,champ=f.Games.Find(g=>g.Round==13).Winner;ClubPlayer retire=f.Starter(1,0);int retireId=retire.Id;retire.Age=38;f.NextSeason();Check(f.DraftActive&&f.UserGame==null&&f.Prospects.Count<=60,"draft blocks kickoff until roster picks finish");Check(f.DraftOrder[0]==worst&&f.DraftOrder[11]==champ,"worst record first and champion last");Check(f.Retired.Exists(p=>p.Id==retireId)&&!f.Players.Exists(p=>p.Id==retireId),"retired player leaves roster and retains historical identity");Check(f.DraftTeam==f.UserTeam,"CPU selects until human is on the clock");int pick=f.DraftPick;f.Save();Franchise reload=Franchise.Load(new Profile(),new Roster());Check(reload.DraftActive&&reload.DraftPick==pick&&reload.Prospects.Count==f.Prospects.Count,"draft board and clock resume from save");f=reload;
  int choices=0;while(f.DraftActive&&choices++<3){ClubPlayer rookie=f.Prospects.Find(p=>f.CanDraft(p,f.UserTeam));Check(rookie!=null&&f.DraftPlayer(rookie.Id),"human selects rookie in round "+choices);}Check(!f.DraftActive&&f.DraftResults.Count==36&&choices==3&&f.UserGame!=null,"three human choices produce exactly 36 league picks");HashSet<int> ids=new HashSet<int>();bool unique=true,rounds=true;foreach(DraftSelection d in f.DraftResults){unique&=ids.Add(d.PlayerId);rounds&=d.Team==f.DraftOrder[(d.Pick-1)%12]&&d.Round==(d.Pick-1)/12+1;}Check(unique&&rounds,"picks have unique players and repeat the correct order each round");
  bool healthy=true,varied=false,staff=false,young=false;HashSet<int> ratings=new HashSet<int>();for(int year=0;year<7;year++){f.Credits=100;FinishSeason(f);foreach(LeagueTeam t in f.Teams){HashSet<int> slots=new HashSet<int>();foreach(ClubPlayer p in f.Squad(t.Id)){if(p.Slot>=0)healthy&=slots.Add(p.Slot)&&Franchise.Roles[p.Slot]==p.Role;healthy&=p.Age<39&&p.OVR>=70&&p.OVR<=99;young|=p.Age<=22;}healthy&=slots.Count==22&&f.Squad(t.Id).Count<=Franchise.MaxRoster&&f.Payroll(t.Id)<=Franchise.Cap;ratings.Add(f.Rating(t.Id,false));staff|=t.Id!=f.UserTeam&&(t.CoachOff>0||t.CoachDef>0);}
   Console.WriteLine("League season "+f.Season+": ratings "+string.Join(",",ratings)+" / retired "+f.Retired.Count);f.NextSeason();f.AutoDraft();healthy&=!f.DraftActive&&f.DraftResults.Count==36;}
  varied=ratings.Count>=8;Check(healthy,"eight seasons preserve caps, roster limits, valid lineups and complete drafts");Check(varied&&staff&&young&&f.Retired.Count>30,"clubs diverge, coach, draft and turn over veterans across seasons");
  f=New();ClubPlayer star=f.Starter(f.UserTeam,0);star.OVR=99;star.Years=1;int before=star.Salary;f.Credits=100;Check(f.Renew(star.Id)&&star.Salary==Franchise.ContractSalary(99)&&star.Salary>before,"renewing a developed star pays his new value");foreach(ClubPlayer p in f.Squad(f.UserTeam))p.Salary=10;ClubPlayer target=f.FreeAgents()[0];Check(!f.Sign(target.Id)&&!f.Renew(star.Id),"over-cap legacy clubs cannot sign or renew more talent");
  f=New();f.LeagueDevelopmentVersion=0;foreach(ClubPlayer p in f.Players)p.Potential=0;int team=f.UserTeam,ovr=f.Starter(team,0).OVR;f.EnsureLeagueDevelopment();int cash=f.BusinessFor(1).Cash;f.EnsureLeagueDevelopment();Check(f.UserTeam==team&&f.Starter(team,0).OVR==ovr&&f.Starter(team,0).Potential>=ovr&&f.BusinessFor(1).Cash==cash,"legacy migration keeps user roster and initializes AI once");
 }finally{Profile.StorageOverride=old;if(Directory.Exists(folder))Directory.Delete(folder,true);}Console.WriteLine("League development: "+checks+" checks, "+failures+" failures");return failures;}
}
}
